function shuffleArray(array){const shuffled=[...array];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]]}
return shuffled}
function positionLogos(){const integrationsSection=document.querySelector('.integrations-section');if(!integrationsSection)return;const logosContainer=integrationsSection.querySelector('.logos-container');if(!logosContainer)return;const rectangleBoxes=Array.from(integrationsSection.querySelectorAll('[class*="rectangle-"]')).filter(rect=>rect.classList.contains('logo-box'));const logoElements=Array.from(integrationsSection.querySelectorAll('.slack, .teams, .zapier, .notion, .asana, .shopify, .trello, .whatsapp, .github, .atlassian, .mailchimp, .g-calendar, .dropbox, .g-drive, .jira, .figma, .discord, .intercom'));const isMobile=window.matchMedia('(max-width: 768px)').matches;if(isMobile){logoElements.forEach((logo,index)=>{if(index<rectangleBoxes.length){const rect=rectangleBoxes[index];if(logo.parentNode!==rect){if(!logo.dataset.originalParent){logo.dataset.originalParent=logo.parentNode===logosContainer?'container':'other'}
rect.appendChild(logo)}
logo.style.position='absolute';logo.style.left='50%';logo.style.top='50%';logo.style.transform='translate(-50%, -50%)';logo.style.width='57px';logo.style.height='57px';logo.style.margin='0';logo.style.padding='0';logo.style.zIndex='2'}})}else{logoElements.forEach(logo=>{if(logo.parentNode!==logosContainer&&logo.parentNode.classList.contains('rectangle-')){if(logo.dataset.originalParent==='container'||!logo.dataset.originalParent){logosContainer.appendChild(logo)}}
logo.style.width='';logo.style.height=''});const rectanglePositions=rectangleBoxes.map(rect=>{const style=window.getComputedStyle(rect);return{element:rect,left:parseFloat(style.left)||0,top:parseFloat(style.top)||0,width:parseFloat(style.width)||0,height:parseFloat(style.height)||0}});const shuffledPositions=shuffleArray(rectanglePositions);logoElements.forEach((logo,index)=>{if(index<shuffledPositions.length){const rectPos=shuffledPositions[index];const logoStyle=window.getComputedStyle(logo);const logoWidth=parseFloat(logoStyle.width)||76.9;const logoHeight=parseFloat(logoStyle.height)||76.9;const centerX=rectPos.left+(rectPos.width/2)-(logoWidth/2);const centerY=rectPos.top+(rectPos.height/2)-(logoHeight/2);logo.style.position='absolute';logo.style.left=centerX+'px';logo.style.top=centerY+'px';logo.style.zIndex='10';logo.style.transform='none'}})}}
document.addEventListener('DOMContentLoaded',function(){const integrationsSection=document.querySelector('.integrations-section');if(!integrationsSection)return;const logosContainer=integrationsSection.querySelector('.logos-container');if(!logosContainer)return;const rectangleBoxes=Array.from(integrationsSection.querySelectorAll('[class*="rectangle-"]')).filter(rect=>rect.classList.contains('logo-box'));const logoElements=Array.from(integrationsSection.querySelectorAll('.slack, .teams, .zapier, .notion, .asana, .shopify, .trello, .whatsapp, .github, .atlassian, .mailchimp, .g-calendar, .dropbox, .g-drive, .jira, .figma, .discord, .intercom'));function initLogoPositioning(){positionLogos();requestAnimationFrame(()=>{requestAnimationFrame(()=>{positionLogos()})})}
setTimeout(initLogoPositioning,50);if(document.readyState==='complete'){initLogoPositioning()}else{window.addEventListener('load',initLogoPositioning)}
let resizeTimeout;window.addEventListener('resize',function(){clearTimeout(resizeTimeout);resizeTimeout=setTimeout(()=>{positionLogos();requestAnimationFrame(()=>{requestAnimationFrame(()=>{positionLogos()})})},150)});const logoBoxes=integrationsSection.querySelectorAll('.logo-box');logoBoxes.forEach(box=>{TweenMax.set(box,{autoAlpha:0,y:-10,scale:0.94})});const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){var tl=new TimelineMax();logoBoxes.forEach(function(el){var dRand=getRandomInt(0,0.28);tl.to(el,0.5,{autoAlpha:1,y:0,scale:1,ease:Power1.easeOut},dRand)});observer.unobserve(entry.target)}})},{threshold:0.2,rootMargin:'0px'});if(integrationsSection){observer.observe(integrationsSection)}
const logos=integrationsSection.querySelectorAll('.slack, .teams, .zapier, .notion, .asana, .shopify, .trello, .whatsapp, .github, .atlassian, .mailchimp, .g-calendar, .dropbox, .g-drive, .jira, .figma, .discord, .intercom');const rectangles=integrationsSection.querySelectorAll('[class*="rectangle-"]');function findClosestRectangle(logo){const logoLeft=parseFloat(getComputedStyle(logo).left)||0;const logoTop=parseFloat(getComputedStyle(logo).top)||0;const logoWidth=parseFloat(getComputedStyle(logo).width)||0;const logoHeight=parseFloat(getComputedStyle(logo).height)||0;const logoCenterX=logoLeft+logoWidth/2;const logoCenterY=logoTop+logoHeight/2;let closestRect=null;let minDistance=Infinity;rectangles.forEach(rect=>{const rectLeft=parseFloat(getComputedStyle(rect).left)||0;const rectTop=parseFloat(getComputedStyle(rect).top)||0;const rectWidth=parseFloat(getComputedStyle(rect).width)||0;const rectHeight=parseFloat(getComputedStyle(rect).height)||0;const rectCenterX=rectLeft+rectWidth/2;const rectCenterY=rectTop+rectHeight/2;const distance=Math.sqrt(Math.pow(logoCenterX-rectCenterX,2)+Math.pow(logoCenterY-rectCenterY,2));if(distance<minDistance){minDistance=distance;closestRect=rect}});return closestRect}
logos.forEach(logo=>{let hoveredRect=null;logo.addEventListener('mouseenter',function(){hoveredRect=findClosestRectangle(logo);if(hoveredRect){hoveredRect.classList.add('logo-hover')}});logo.addEventListener('mouseleave',function(){if(hoveredRect){hoveredRect.classList.remove('logo-hover');hoveredRect=null}})})})</script> </div></div><div
